SELECT ?publication ?doi ?label ?description
       (GROUP_CONCAT(DISTINCT CONCAT(?inv, " || ", ?invl, " || ", ?invd, " || ", ?inv_class); SEPARATOR=" <|> ") AS ?invents)
       (GROUP_CONCAT(DISTINCT CONCAT(?doc, " || ", ?docl, " || ", ?docd, " || ", ?doc_class); SEPARATOR=" <|> ") AS ?documents)
       (GROUP_CONCAT(DISTINCT CONCAT(?stu, " || ", ?stul, " || ", ?stud, " || ", ?stu_class); SEPARATOR=" <|> ") AS ?studies)
       (GROUP_CONCAT(DISTINCT CONCAT(?rev, " || ", ?revl, " || ", ?revd, " || ", ?rev_class); SEPARATOR=" <|> ") AS ?surveys)
       (GROUP_CONCAT(DISTINCT CONCAT(?use, " || ", ?usel, " || ", ?used, " || ", ?use_class); SEPARATOR=" <|> ") AS ?uses)
       (GROUP_CONCAT(DISTINCT CONCAT(?ana, " || ", ?anal, " || ", ?anad, " || ", ?ana_class); SEPARATOR=" <|> ") AS ?analyzes)
       (GROUP_CONCAT(DISTINCT CONCAT(?app, " || ", ?appl, " || ", ?appd, " || ", ?app_class); SEPARATOR=" <|> ") AS ?applies)

WHERE { VALUES ?publication { wd:Q2643268 }

  OPTIONAL {
    ?invraw p:P286 ?statement1.
    ?statement1 ps:P286 ?publication.
    BIND(CONCAT("mardi:", STRAFTER(STR(?invraw), STR(wd:))) AS ?inv)

    OPTIONAL {
      ?invraw rdfs:label ?invlraw.
      FILTER (lang(?invlraw) = 'en')
    }
    BIND(COALESCE(?invlraw, "No Label Provided!") AS ?invl)

    OPTIONAL {
      ?invraw schema:description ?invdraw
      FILTER (lang(?invdraw) = 'en')
    }
    BIND(COALESCE(?invdraw, "No Description Provided!") AS ?invd)

    OPTIONAL { ?invraw wdt:P31 ?inv_type_raw. }
    BIND(IF(BOUND(?inv_type_raw), CONCAT("mardi:", STRAFTER(STR(?inv_type_raw), STR(wd:))), "") AS ?inv_class)

    ?statement1 pq:P560 wd:Q6672344.
  }

  OPTIONAL {
    ?docraw p:P286 ?statement2.
    ?statement2 ps:P286 ?publication.
    BIND(CONCAT("mardi:", STRAFTER(STR(?docraw), STR(wd:))) AS ?doc)

    OPTIONAL {
      ?docraw rdfs:label ?doclraw.
      FILTER (lang(?doclraw) = 'en')
    }
    BIND(COALESCE(?doclraw, "No Label Provided!") AS ?docl)

    OPTIONAL {
      ?docraw schema:description ?docdraw
      FILTER (lang(?docdraw) = 'en')
    }
    BIND(COALESCE(?docdraw, "No Description Provided!") AS ?docd)

    OPTIONAL { ?docraw wdt:P31 ?doc_type_raw. }
    BIND(IF(BOUND(?doc_type_raw), CONCAT("mardi:", STRAFTER(STR(?doc_type_raw), STR(wd:))), "") AS ?doc_class)

    ?statement2 pq:P560 wd:Q6672349.
  }

  OPTIONAL {
    ?sturaw p:P286 ?statement3.
    ?statement3 ps:P286 ?publication.
    BIND(CONCAT("mardi:", STRAFTER(STR(?sturaw), STR(wd:))) AS ?stu)

    OPTIONAL {
      ?sturaw rdfs:label ?stulraw.
      FILTER (lang(?stulraw) = 'en')
    }
    BIND(COALESCE(?stulraw, "No Label Provided!") AS ?stul)

    OPTIONAL {
      ?sturaw schema:description ?studraw
      FILTER (lang(?studraw) = 'en')
    }
    BIND(COALESCE(?studraw, "No Description Provided!") AS ?stud)

    OPTIONAL { ?sturaw wdt:P31 ?stu_type_raw. }
    BIND(IF(BOUND(?stu_type_raw), CONCAT("mardi:", STRAFTER(STR(?stu_type_raw), STR(wd:))), "") AS ?stu_class)

    ?statement3 pq:P560 wd:Q6775621.
  }

  OPTIONAL {
    ?revraw p:P286 ?statement4.
    ?statement4 ps:P286 ?publication.
    BIND(CONCAT("mardi:", STRAFTER(STR(?revraw), STR(wd:))) AS ?rev)

    OPTIONAL {
      ?revraw rdfs:label ?revlraw.
      FILTER (lang(?revlraw) = 'en')
    }
    BIND(COALESCE(?revlraw, "No Label Provided!") AS ?revl)

    OPTIONAL {
      ?revraw schema:description ?revdraw
      FILTER (lang(?revdraw) = 'en')
    }
    BIND(COALESCE(?revdraw, "No Description Provided!") AS ?revd)

    OPTIONAL { ?revraw wdt:P31 ?rev_type_raw. }
    BIND(IF(BOUND(?rev_type_raw), CONCAT("mardi:", STRAFTER(STR(?rev_type_raw), STR(wd:))), "") AS ?rev_class)

    ?statement4 pq:P560 wd:Q6672366.
  }

  OPTIONAL {
    ?useraw p:P286 ?statement5.
    ?statement5 ps:P286 ?publication.
    BIND(CONCAT("mardi:", STRAFTER(STR(?useraw), STR(wd:))) AS ?use)

    OPTIONAL {
      ?useraw rdfs:label ?uselraw.
      FILTER (lang(?uselraw) = 'en')
    }
    BIND(COALESCE(?uselraw, "No Label Provided!") AS ?usel)

    OPTIONAL {
      ?useraw schema:description ?usedraw
      FILTER (lang(?usedraw) = 'en')
    }
    BIND(COALESCE(?usedraw, "No Description Provided!") AS ?used)

    OPTIONAL { ?useraw wdt:P31 ?use_type_raw. }
    BIND(IF(BOUND(?use_type_raw), CONCAT("mardi:", STRAFTER(STR(?use_type_raw), STR(wd:))), "") AS ?use_class)

    ?statement5 pq:P560 wd:Q6480405.
  }

  OPTIONAL {
    ?anaraw p:P286 ?statement6.
    ?statement6 ps:P286 ?publication.
    BIND(CONCAT("mardi:", STRAFTER(STR(?anaraw), STR(wd:))) AS ?ana)

    OPTIONAL {
      ?anaraw rdfs:label ?analraw.
      FILTER (lang(?analraw) = 'en')
    }
    BIND(COALESCE(?analraw, "No Label Provided!") AS ?anal)

    OPTIONAL {
      ?anaraw schema:description ?anadraw
      FILTER (lang(?anadraw) = 'en')
    }
    BIND(COALESCE(?anadraw, "No Description Provided!") AS ?anad)

    OPTIONAL { ?anaraw wdt:P31 ?ana_type_raw. }
    BIND(IF(BOUND(?ana_type_raw), CONCAT("mardi:", STRAFTER(STR(?ana_type_raw), STR(wd:))), "") AS ?ana_class)

    ?statement6 pq:P560 wd:Q6825292.
  }

  OPTIONAL {
    ?appraw p:P286 ?statement7.
    ?statement7 ps:P286 ?publication.
    BIND(CONCAT("mardi:", STRAFTER(STR(?appraw), STR(wd:))) AS ?app)

    OPTIONAL {
      ?appraw rdfs:label ?applraw.
      FILTER (lang(?applraw) = 'en')
    }
    BIND(COALESCE(?applraw, "No Label Provided!") AS ?appl)

    OPTIONAL {
      ?appraw schema:description ?appdraw
      FILTER (lang(?appdraw) = 'en')
    }
    BIND(COALESCE(?appdraw, "No Description Provided!") AS ?appd)

    OPTIONAL { ?appraw wdt:P31 ?app_type_raw. }
    BIND(IF(BOUND(?app_type_raw), CONCAT("mardi:", STRAFTER(STR(?app_type_raw), STR(wd:))), "") AS ?app_class)

    ?statement7 pq:P560 wd:Q6825298.
  }

  OPTIONAL {
    ?publication wdt:P27 ?doi.
  }

  SERVICE wikibase:label {
    bd:serviceParam wikibase:language "en,mul".
    ?publication rdfs:label ?labelraw.
    ?publication schema:description ?descriptionraw.
  }

  BIND(COALESCE(?labelraw, "No Label Provided!") AS ?label)
  BIND(COALESCE(?descriptionraw, "No Description Provided!") AS ?description)

}
GROUP BY ?publication ?doi ?label ?description
